// Supabase Edge Function: share-progress
// Cloud-backed share codes for progress links. POST uploads a deflate-raw
// progress payload and returns a three-word code ('apple-orange-grape',
// generated by the share_code() SQL function); GET with ?code= returns the
// stored payload. Same protections as the other functions: banlist, salted
// IP fingerprint, per-IP rate limits.
//
// Deploy:  supabase functions deploy share-progress
// Invoke:  POST https://<project>.supabase.co/functions/v1/share-progress
//          { "payload": "<base64url deflate-raw bytes>", "device_id": "..." }
//          GET  https://<project>.supabase.co/functions/v1/share-progress?code=apple-orange-grape

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const SERVICE =
  Deno.env.get('SUPABASE_SECRET_KEY') ??
  Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ??
  '';
const URL = Deno.env.get('SUPABASE_URL') ?? '';
const SALT = Deno.env.get('REPORT_SALT') ?? '';
const admin = createClient(URL, SERVICE);

// sharing is deliberate and rare
const WRITE_HOURLY_LIMIT = 10;
const WRITE_DAILY_LIMIT = 30;
const READ_HOURLY_LIMIT = 120;
const PAYLOAD_MAX = 65536;
const PAYLOAD_MIN = 4;
// three lowercase words joined by '-' (the share_code() word list)
const CODE_RE = /^[a-z]{3,8}(-[a-z]{3,8}){2}$/;

const sha256 = async (text) =>
  [...new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)))]
    .map((b) => b.toString(16).padStart(2, '0')).join('');

const cors = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'GET, POST, OPTIONS',
  'access-control-allow-headers': 'authorization, content-type',
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...cors, 'content-type': 'application/json' },
  });
}

async function rateLimited(ipHash, hourlyLimit, dailyLimit) {
  const { count: hourCount } = await admin
    .from('report_log')
    .select('*', { count: 'exact', head: true })
    .eq('ip_hash', ipHash)
    .gte('created_at', new Date(Date.now() - 3600_000).toISOString());
  if ((hourCount ?? 0) >= hourlyLimit) return true;
  const { count: dayCount } = await admin
    .from('report_log')
    .select('*', { count: 'exact', head: true })
    .eq('ip_hash', ipHash)
    .gte('created_at', new Date(Date.now() - 86_400_000).toISOString());
  return (dayCount ?? 0) >= dailyLimit;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
  if (req.method !== 'POST' && req.method !== 'GET') return json({ error: 'POST or GET only' }, 405);

  try {
    const ip = (req.headers.get('cf-connecting-ip') ??
      (req.headers.get('x-forwarded-for') ?? '').split(',')[0].trim()) || 'unknown';
    const ipHash = await sha256(ip + SALT);

    // banlist applies to both directions
    const { data: banned } = await admin
      .from('report_bans')
      .select('value')
      .eq('value', ipHash);
    if (banned && banned.length) return json({ error: 'banned' }, 403);

    if (req.method === 'GET') {
      const code = String(new URL(req.url).searchParams.get('code') ?? '').toLowerCase().slice(0, 40);
      if (!CODE_RE.test(code)) return json({ error: 'invalid code' }, 400);
      if (await rateLimited(ipHash, READ_HOURLY_LIMIT, READ_HOURLY_LIMIT * 3)) return json({ error: 'rate limited' }, 429);
      const { data: row } = await admin
        .from('share_codes')
        .select('payload')
        .eq('code', code)
        .maybeSingle();
      if (!row) return json({ error: 'unknown code' }, 404);
      return json({ ok: true, payload: row.payload });
    }

    // POST: create a share code
    const body = await req.json().catch(() => ({}));
    const payload = String(body.payload ?? '');
    const deviceId = String(body.device_id ?? '').slice(0, 64);
    if (payload.length < PAYLOAD_MIN || payload.length > PAYLOAD_MAX || !/^[A-Za-z0-9_-]+$/.test(payload)) {
      return json({ error: 'invalid payload' }, 400);
    }
    if (!deviceId || deviceId.length < 8) return json({ error: 'invalid device' }, 400);
    const fingerprint = await sha256(deviceId + ipHash + SALT);
    if (await rateLimited(ipHash, WRITE_HOURLY_LIMIT, WRITE_DAILY_LIMIT)) return json({ error: 'rate limited (share)' }, 429);

    // append to the log + prune rows older than a day (opportunistic)
    await admin.from('report_log').insert({ ip_hash: ipHash });
    await admin.from('report_log').delete().lt('created_at', new Date(Date.now() - 172_800_000).toISOString());

    // mint a 3-word code via SQL (retry on the rare collision)
    for (let attempt = 0; attempt < 5; attempt++) {
      const { data: gen, error: rpcErr } = await admin.rpc('share_code');
      if (rpcErr) return json({ error: 'code gen: ' + String(rpcErr.message).slice(0, 160) }, 500);
      const code = String(gen ?? '').toLowerCase();
      if (!CODE_RE.test(code)) return json({ error: 'code gen returned: ' + String(gen).slice(0, 60) }, 500);
      const { error: insErr } = await admin.from('share_codes').insert({
        code, payload, size: payload.length, device_id: deviceId, ip_hash: ipHash,
      });
      if (!insErr) return json({ ok: true, code });
      if (!String(insErr.message).includes('duplicate key')) {
        return json({ error: 'insert failed: ' + String(insErr.message).slice(0, 160) }, 500);
      }
    }
    return json({ error: 'could not mint a code' }, 500);
  } catch (err) {
    return json({ error: String(err?.message ?? err).slice(0, 160) }, 500);
  }
});
